impl Solution {
    pub fn count_routes(locations: Vec<i32>, start: i32, finish: i32, fuel: i32) -> i32 {
        const MOD: i32 = 10i32.pow(9) + 7;
        let n = locations.len() as i32;
        let start = start as usize;
        let finish = finish as usize;
        let mut dp = vec![vec![0; n]; fuel as usize + 1];
        dp[0][start] = 1;

        for f in 1..=fuel as usize {
            for i in 0..n {
                if dp[f - 1][i] == 0 {
                    continue;
                }
                for j in 0..n {
                    if i == j {
                        continue;
                    }
                    let cost = (locations[i] as i32 - locations[j] as i32).abs();
                    if f >= cost as usize {
                        dp[f][j] = (dp[f][j] + dp[f - cost as usize][i]) % MOD;
                    }
                }
            }
        }

        let mut result = 0;
        for f in 0..=fuel as usize {
            result = (result + dp[f][finish]) % MOD;
        }
        result
    }
}
